import re

def solve(env, goal):
    # Parse goal: "put a clean <object> in/on <receptacle>."
    m = re.search(r'put a clean (\w+) (?:in|on) (?:a |an |the )?(\w+)', goal, re.I)
    if not m:
        m = re.search(r'put a (\w+) (?:in|on) (?:a |an |the )?(\w+)', goal, re.I)
    if not m:
        return
    target_obj = m.group(1).lower()
    target_rec = m.group(2).lower()

    opened = set()
    holding = None

    def obs():
        return env.observation

    def do(cmd):
        return env.step(cmd)

    def is_closed(rec):
        return rec not in opened

    def open_rec(rec):
        if rec in opened:
            return True
        r = do('open ' + rec)
        if 'you open' in r.lower() or 'is open' in r.lower() or 'already open' in r.lower():
            opened.add(rec)
            return True
        return False

    def close_rec(rec):
        if rec in opened:
            do('close ' + rec)
            opened.discard(rec)

    # Get list of receptacles from initial observation
    initial = obs()
    recs = re.findall(r'\b([a-z]+(?:[a-z]*)? \d+)\b', initial)
    all_recs = []
    seen = set()
    for r in recs:
        if r not in seen:
            seen.add(r)
            all_recs.append(r)

    def recs_of_type(t):
        return [r for r in all_recs if r.rsplit(' ', 1)[0] == t]

    def parse_inventory(text):
        if 'carrying nothing' in text.lower() or 'inventory is empty' in text.lower():
            return []
        m = re.search(r'carrying (?:a |an )?(.*)', text, re.I)
        if m:
            items = m.group(1).strip().rstrip('.')
            return [items] if items else []
        return []

    def extract_objects(text):
        found = re.findall(r'\b([a-z]+(?:[a-z]*)? \d+)\b', text)
        # Filter out receptacle names (those with type in known receptacle types)
        rec_types = set(r.rsplit(' ', 1)[0] for r in all_recs)
        out = []
        for f in found:
            if f.rsplit(' ', 1)[0] not in rec_types:
                out.append(f)
        return out

    # Search receptacles for object, taking it when found.
    def find_and_take(obj_type):
        # Check inventory first
        inv = do('inventory')
        items = parse_inventory(inv)
        for it in items:
            if it.rsplit(' ', 1)[0] == obj_type:
                return it
        for rec in all_recs:
            r_name = rec.rsplit(' ', 1)[0]
            # Skip non-container receptacles that can't hold objects (lamps, etc.)
            if r_name in ('lamp', 'toaster', 'coffeemachine', 'stoveburner'):
                continue
            r = do('go to ' + rec)
            if 'closed' in r.lower():
                if not open_rec(rec):
                    continue
            r2 = do('look')
            text = r + ' ' + r2
            objs = extract_objects(text)
            for f in objs:
                if f.rsplit(' ', 1)[0] == obj_type:
                    tr = do('take ' + f + ' from ' + rec)
                    if 'pick up' in tr.lower() or 'you pick' in tr.lower():
                        return f
            if r_name in ('drawer', 'cabinet', 'fridge', 'microwave', 'safe'):
                close_rec(rec)
        return None

    obj = find_and_take(target_obj)
    if obj is None:
        return

    # Clean it with sink basin
    sinks = recs_of_type('sinkbasin')
    if sinks:
        sink = sinks[0]
        do('go to ' + sink)
        r = do('clean ' + obj + ' with ' + sink)
        if 'clean' not in r.lower():
            # maybe need to be at sink; try again
            do('clean ' + obj + ' with ' + sink)

    # Go to target receptacle
    recs_target = recs_of_type(target_rec)
    if not recs_target:
        recs_target = [r for r in all_recs if target_rec in r]
    if not recs_target:
        return
    dest = recs_target[0]
    r = do('go to ' + dest)
    if 'closed' in r.lower():
        open_rec(dest)
    do('move ' + obj + ' to ' + dest)
